import { writeFileSync } from 'node:fs';
import { redirects } from '../redirects.mjs';

const lines = [
  '# Generated by scripts/generate-redirects.mjs. Do not edit by hand.',
  '# Netlify and Cloudflare Pages understand this format.',
  '',
];

for (const [from, to] of Object.entries(redirects)) {
  lines.push(`${from}/ ${to} 301`);
}

writeFileSync(new URL('../public/_redirects', import.meta.url), `${lines.join('\n')}\n`, 'utf8');
console.log(`Wrote ${Object.keys(redirects).length} redirects to public/_redirects`);
